create type public.approval_decision as enum ('PENDING','APPROVED','REJECTED');
create table public.approval_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,entity_type text not null check(entity_type ~ '^[A-Z][A-Z_]{1,79}$'),entity_id uuid not null,stage text not null check(length(trim(stage)) between 2 and 100),requested_by uuid not null references public.user_profiles(id) on delete restrict,approver_id uuid not null references public.user_profiles(id) on delete restrict,decision public.approval_decision not null default 'PENDING',comment text,decided_at timestamptz,created_at timestamptz not null default now(),check(requested_by<>approver_id));
create index approval_requests_entity_idx on public.approval_requests(organization_id,entity_type,entity_id,decision);alter table public.approval_requests enable row level security;create policy "management reads approvals" on public.approval_requests for select to authenticated using(public.has_ticket_management_role(organization_id));
create or replace function public.request_change_approval(target_change_id uuid,target_approver_id uuid,target_stage text default 'CHANGE_MANAGER') returns uuid language plpgsql security definer set search_path=public as $$ declare c public.changes%rowtype; approval_id uuid;begin select * into c from public.changes where id=target_change_id for update;if c.id is null or not public.has_ticket_management_role(c.organization_id) then raise exception 'APPROVAL_NOT_AUTHORIZED';end if;if target_approver_id=auth.uid() or not exists(select 1 from public.user_roles where user_id=target_approver_id and organization_id=c.organization_id and role in('SUPER_ADMIN','ORG_ADMIN','MANAGER')) then raise exception 'APPROVAL_INVALID_APPROVER';end if;insert into public.approval_requests(organization_id,entity_type,entity_id,stage,requested_by,approver_id) values(c.organization_id,'CHANGE',c.id,trim(target_stage),auth.uid(),target_approver_id) returning id into approval_id;update public.changes set status='AWAITING_APPROVAL' where id=c.id;insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(c.organization_id,auth.uid(),'CHANGE_APPROVAL_REQUESTED','change',c.id,jsonb_build_object('approval_id',approval_id,'approver_id',target_approver_id),'WEB');return approval_id;end;$$;
create or replace function public.decide_change_approval(target_approval_id uuid,target_decision public.approval_decision,target_comment text default null) returns void language plpgsql security definer set search_path=public as $$ declare a public.approval_requests%rowtype;begin select * into a from public.approval_requests where id=target_approval_id for update;if a.id is null or a.approver_id<>auth.uid() or a.decision<>'PENDING' then raise exception 'APPROVAL_DECISION_NOT_AUTHORIZED';end if;if target_decision not in('APPROVED','REJECTED') then raise exception 'APPROVAL_INVALID_DECISION';end if;if target_decision='REJECTED' and length(trim(target_comment)) not between 10 and 2000 then raise exception 'APPROVAL_REJECTION_COMMENT_REQUIRED';end if;update public.approval_requests set decision=target_decision,comment=nullif(trim(target_comment),''),decided_at=clock_timestamp() where id=a.id;update public.changes set status=case when target_decision='APPROVED' then 'APPROVED' else 'ASSESSMENT' end where id=a.entity_id and entity_type='CHANGE';insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(a.organization_id,auth.uid(),'CHANGE_APPROVAL_DECIDED','change',a.entity_id,jsonb_build_object('approval_id',a.id,'decision',target_decision),'WEB');end;$$;
revoke all on function public.request_change_approval(uuid,uuid,text),public.decide_change_approval(uuid,public.approval_decision,text) from public;grant execute on function public.request_change_approval(uuid,uuid,text),public.decide_change_approval(uuid,public.approval_decision,text) to authenticated;
